let rawTime = msg.payload[1];
let status  = msg.payload[2];

if (!rawTime || status === undefined) {
    node.warn("Unexpected payload shape: " + JSON.stringify(msg.payload));
    return null;
}

let time = rawTime.split('.')[0].replace('T', ' ');

let statusColor = (status === "Submission received") ? "#4CAF50" : "#F44336";

msg.payload = "<b>Submission Time: </b> " + time +
    "<br/><b>Submission Status: </b>" +
    "<span style='color: " + statusColor + "; font-weight: bold;'>" + status + "</span>";

return msg;

// 1. 初始化
let history = global.get("audit_history") || [];
let currentFilter = context.get("currentFilter") || "all";

// 2. 识别来源 (根据你的 Debug 截图适配)
if (msg.topic === "filter_command") {
    // 适配你 Dropdown 的实际输出值
    if (msg.payload === "Received") {
        currentFilter = "success";
    } else if (msg.payload === "Others") {
        currentFilter = "error";
    } else {
        currentFilter = "all";
    }
    context.set("currentFilter", currentFilter);
}
else if (Array.isArray(msg.payload)) {
    // 处理 OPC UA 新数据
    let id = msg.payload[0];
    let rawTime = msg.payload[1];
    let time = rawTime ? rawTime.split('.')[0].replace('T', ' ') : "";
    let status = msg.payload[2] ? msg.payload[2].trim() : "";

    let isSuccess = (status === "Submission received");
    let color = isSuccess ? "#4CAF50" : "#f44336";
    const format = (text) => `<span style="color: ${color}; font-weight: bold;">${text}</span>`;

    history.unshift({
        time: format(time),
        status: format(status),
        id: format(id),
        isSuccess: isSuccess
    });

    if (history.length > 100) history.pop();
    global.set("audit_history", history);
}

// 3. 执行过滤
let displayData = [];
if (currentFilter === "success") {
    displayData = history.filter(item => item.isSuccess === true);
} else if (currentFilter === "error") {
    displayData = history.filter(item => item.isSuccess === false);
} else {
    displayData = history;
}

// 4. 输出
msg.payload = displayData;
return msg;

